import { QueryClient } from "@tanstack/react-query";
import { createRouter } from "@tanstack/react-router";
// Generated by @tanstack/router-plugin from the files in `src/routes/`.
// Regenerated on every dev/build run — do not edit by hand.
import { routeTree } from "./routeTree.gen";

// Same defaults as client-side: one retry, no refetch on window focus, so the
// only requests you see come from filter changes.
export const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      retry: 1,
      refetchOnWindowFocus: false,
    },
  },
});

export const router = createRouter({
  routeTree,
  // Loaders reach React Query through the router context.
  context: { queryClient },
  // React Query owns caching; don't let the router cache preloaded loader results too.
  defaultPreloadStaleTime: 0,
});

declare module "@tanstack/react-router" {
  interface Register {
    router: typeof router;
  }
}
